import { useState, useEffect, useMemo, useRef } from "react";
import * as XLSX from "xlsx";
import {
  Plus, X, Search, Wrench, AlertTriangle, Clock, CheckCircle2,
  Filter, Trash2, Pencil, Calendar, User, Tag, ClipboardList,
  ChevronDown, GripVertical, LayoutGrid, List as ListIcon, Sun, Moon,
  Download, Upload, Minus
} from "lucide-react";
import { storage } from "../lib/storage";

/* ---------------------------------------------------------
   Planificador de Mantenimiento
   Branding Ferring: azul de marca, tipografía Arial, logo propio
--------------------------------------------------------- */

const FERRING_LOGO_BASE64 = "";

const ICONO_MANTENIMIENTO = "data:image/png;base64,";
const ICONO_PARADA_PLANTA = "data:image/png;base64,";
const ICONO_INDICADORES = "data:image/png;base64,";
const ICONO_CENTRIFUGAS = "data:image/png;base64,";
const ICONO_PROVEEDORES = "data:image/png;base64,";

const ESTADOS = [
  { id: "pendiente", label: "Pendiente", color: "#9AA0A6" },
  { id: "completado", label: "Completado", color: "#6FA97A" },
];

const TIPOS = [
  { id: "preventivo", label: "Preventivo" },
  { id: "correctivo", label: "Correctivo" },
  { id: "predictivo", label: "Predictivo" },
  { id: "mejora", label: "Mejora" },
];

const PRIORIDADES = [
  { id: "baja", label: "Baja", color: "#6FA97A" },
  { id: "media", label: "Media", color: "#4A90A4" },
  { id: "alta", label: "Alta", color: "#E37222" },
  { id: "critica", label: "Crítica", color: "#C1554A" },
];

const STORAGE_KEY = "ot_tasks_v1";
const SEQ_KEY = "ot_seq_v1";
const THEME_KEY = "ot_theme_v1";
const REGISTROS_KEY = "ot_registros_v1";
const TRABAJOS_KEY = "ot_trabajos_v1";
const PARADA_KEY = "ot_parada_planta_v1";
const CENTRIFUGAS_KEY = "ot_centrifugas_v1";
const TANQUES_KEY = "ot_tanques_v1";
const PARADA_UI_KEY = "ot_parada_ui_v1";
const PARADA_PREVIA_KEY = "ot_parada_previa_v1";
const PARADA_PREVIA_UI_KEY = "ot_parada_previa_ui_v1";
const CRONOGRAMA_KEY = "ot_cronograma_v1";
const CRONOGRAMA_UI_KEY = "ot_cronograma_ui_v1";
const PROVEEDORES_KEY = "ot_proveedores_v1";
const PROVEEDORES_ANCHOS_KEY = "ot_proveedores_anchos_v1";
const MESES_COMPLETADO_KEY = "ot_meses_completado_v1";

const MESES_ANIO = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];

const uid = () => Math.random().toString(36).slice(2, 10);
const todayISO = () => new Date().toISOString().slice(0, 10);

function fmtDate(iso) {
  if (!iso) return "—";
  const [y, m, d] = iso.split("-");
  return `${d}/${m}/${y}`;
}

function claveMes(iso) {
  if (!iso) return "sin-fecha";
  return iso.slice(0, 7); // "YYYY-MM"
}

function etiquetaMes(clave) {
  if (clave === "sin-fecha") return "Sin fecha";
  const [y, m] = clave.split("-");
  const d = new Date(Number(y), Number(m) - 1, 1);
  const texto = d.toLocaleDateString("es-AR", { month: "long", year: "numeric" });
  return texto.charAt(0).toUpperCase() + texto.slice(1);
}

function isOverdue(t) {
  return t.fecha && t.fecha < todayISO() && t.estado !== "completado";
}

const emptyForm = () => ({
  id: null,
  titulo: "",
  equipo: "",
  tipo: "preventivo",
  prioridad: "media",
  tecnico: "",
  fecha: todayISO(),
  estado: "pendiente",
  descripcion: "",
  subtareas: [],
});

export default function App() {
  const [theme, setTheme] = useState("dark");
  const [tab, setTab] = useState("parada_planta");
  const [mensajeBackup, setMensajeBackup] = useState("");
  const [soloLectura, setSoloLectura] = useState(true);
  const [modalPassword, setModalPassword] = useState(false);
  const [passwordInput, setPasswordInput] = useState("");
  const [passwordError, setPasswordError] = useState("");

  // La app siempre abre en modo solo lectura (Parada de Planta e
  // Indicadores, sin poder tocar nada). La edición se desbloquea con la
  // contraseña, pero solo dura mientras esta pestaña siga abierta — no se
  // recuerda entre visitas, así que cada carga de página vuelve a pedirla.

  // Título de la pestaña del navegador: "Parada de Planta" en modo solo
  // lectura, "Planificador de Mantenimiento" una vez desbloqueada la edición.
  useEffect(() => {
    try {
      document.title = soloLectura ? "Parada de Planta" : "Planificador de Mantenimiento";
    } catch (e) {
      /* sin acceso al documento (no debería pasar en el navegador) */
    }
  }, [soloLectura]);

  function intentarDesbloquear() {
    const claveEsperada =
      (typeof process !== "undefined" && process.env && process.env.NEXT_PUBLIC_EDIT_PASSWORD) || "";
    if (passwordInput === claveEsperada) {
      setSoloLectura(false);
      setTab("mantenimiento");
      setModalPassword(false);
      setPasswordInput("");
      setPasswordError("");
    } else {
      setPasswordError("Contraseña incorrecta.");
    }
  }

  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(THEME_KEY, false);
        if (res && res.value) setTheme(res.value);
      } catch (e) {
        /* no existe aún, queda el tema por defecto */
      }
    })();
  }, []);

  function cambiarTema() {
    const next = theme === "dark" ? "light" : "dark";
    setTheme(next);
    storage.set(THEME_KEY, next, false).catch(() => {});
  }

  const CLAVES_BACKUP = [STORAGE_KEY, SEQ_KEY, REGISTROS_KEY, TRABAJOS_KEY, PARADA_KEY];

  async function descargarBackup() {
    const backup = {};
    for (const k of CLAVES_BACKUP) {
      try {
        const r = await storage.get(k, false);
        if (r && r.value) backup[k] = r.value;
      } catch (e) {
        /* clave sin datos todavía */
      }
    }
    const blob = new Blob([JSON.stringify(backup)], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `backup-planificador-${todayISO()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  function restaurarBackup(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const datos = JSON.parse(reader.result);
        for (const k of CLAVES_BACKUP) {
          if (datos[k] !== undefined) {
            await storage.set(k, datos[k], false);
          }
        }
        setMensajeBackup("Backup restaurado. Recargando...");
        setTimeout(() => window.location.reload(), 1200);
      } catch (err) {
        setMensajeBackup("No se pudo leer ese archivo como backup válido.");
        setTimeout(() => setMensajeBackup(""), 4000);
      }
    };
    reader.readAsText(file);
    e.target.value = "";
  }

  return (
    <div style={styles.app} className={theme === "dark" ? "theme-dark" : "theme-light"}>
      <style>{`
        * { box-sizing: border-box; }
        .theme-dark {
          --bg: #24272B; --panel: #2C3035; --panel-2: #2F3439;
          --border: #3E434A; --text: #ECE9E2; --text-dim: #9AA0A6;
          --accent: #29A9E0; --scrollbar-thumb: #444A51;
        }
        .theme-light {
          --bg: #F4F2ED; --panel: #FFFFFF; --panel-2: #FBFAF7;
          --border: #DEDAD1; --text: #2A2C2F; --text-dim: #6E7379;
          --accent: #0088CE; --scrollbar-thumb: #D5D0C6;
        }
        ::selection { background: #0088CE55; }
        input, select, textarea, button { font-family: inherit; }
        input, textarea { caret-color: var(--text); }
        input::placeholder, textarea::placeholder { color: var(--text-dim); }
        .scrollbar::-webkit-scrollbar { width: 8px; height: 8px; }
        .scrollbar::-webkit-scrollbar-thumb { background: var(--scrollbar-thumb); border-radius: 4px; }
        .scrollbar::-webkit-scrollbar-track { background: transparent; }
        button:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
          outline: 2px solid var(--accent); outline-offset: 1px;
        }
        .card-hover:hover { border-color: #4A90A4 !important; transform: translateY(-1px); }
        @media (max-width: 720px) {
          .top-controls { flex-wrap: wrap; }
          .main-grid { grid-template-columns: 1fr !important; }
          .divider-line { display: none; }
        }
      `}</style>

      <button
        onClick={cambiarTema}
        title={theme === "dark" ? "Cambiar a modo claro" : "Cambiar a modo oscuro"}
        style={styles.themeToggle}
      >
        {theme === "dark" ? <Sun size={16} /> : <Moon size={16} />}
      </button>

      <button
        onClick={descargarBackup}
        title="Descargar backup completo de todos los datos (Mantenimiento y Parada de Planta)"
        style={{ ...styles.themeToggle, bottom: 70 }}
      >
        <Download size={16} />
      </button>

      <label
        title="Restaurar un backup descargado antes"
        style={{ ...styles.themeToggle, bottom: 120, cursor: "pointer" }}
      >
        <Upload size={16} />
        <input type="file" accept=".json,application/json" onChange={restaurarBackup} style={{ display: "none" }} />
      </label>

      {mensajeBackup && (
        <div style={styles.backupBanner}>{mensajeBackup}</div>
      )}

      {/* Franja de acento superior */}
      <div style={styles.topAccentBar} />

      {/* Logo Ferring */}
      <div style={styles.ferringBar}>
        <img src={`data:image/png;base64,${FERRING_LOGO_BASE64}`} alt="Ferring" style={styles.ferringLogo} />
      </div>

      {/* Pestañas */}
      <div style={styles.tabBar}>
        {!soloLectura && (
          <button
            style={{ ...styles.tabBtn, ...(tab === "mantenimiento" ? styles.tabBtnActive : {}) }}
            onClick={() => setTab("mantenimiento")}
          >
            Mantenimiento
          </button>
        )}
        <button
          style={{ ...styles.tabBtn, ...(tab === "parada_planta" ? styles.tabBtnActive : {}) }}
          onClick={() => setTab("parada_planta")}
        >
          Parada de Planta
        </button>
        <button
          style={{ ...styles.tabBtn, ...(tab === "indicadores" ? styles.tabBtnActive : {}) }}
          onClick={() => setTab("indicadores")}
        >
          Indicadores
        </button>
        {!soloLectura && (
          <button
            style={{ ...styles.tabBtn, ...(tab === "centrifugas" ? styles.tabBtnActive : {}) }}
            onClick={() => setTab("centrifugas")}
          >
            Centrífugas y tanques
          </button>
        )}
        {!soloLectura && (
          <button
            style={{ ...styles.tabBtn, ...(tab === "proveedores" ? styles.tabBtnActive : {}) }}
            onClick={() => setTab("proveedores")}
          >
            Proveedores
          </button>
        )}
        {soloLectura && (
          <button style={styles.soloLecturaBadge} onClick={() => setModalPassword(true)}>
            🔒 Solo lectura — Modo edición
          </button>
        )}
      </div>

      <div style={soloLectura ? { pointerEvents: "none" } : undefined}>
        {tab === "mantenimiento" ? <MantenimientoTab />
          : tab === "parada_planta" ? <ParadaPlantaTab />
          : tab === "indicadores" ? <IndicadoresTab />
          : tab === "centrifugas" ? <CentrifugasTab />
          : <ProveedoresTab />}
      </div>

      {modalPassword && (
        <div
          style={styles.overlay}
          onMouseDown={(e) => { if (e.target === e.currentTarget) setModalPassword(false); }}
        >
          <div style={{ ...styles.modal, maxWidth: 340 }}>
            <div style={styles.modalHeader}>
              <span style={styles.modalTitle}>Desbloquear edición</span>
              <button type="button" style={styles.iconClose} onClick={() => setModalPassword(false)}>
                <X size={16} />
              </button>
            </div>
            <div style={styles.modalBody}>
              {passwordError && (
                <div style={styles.formErrorBanner}>
                  <AlertTriangle size={14} /> {passwordError}
                </div>
              )}
              <Field label="Contraseña">
                <input
                  type="password"
                  style={styles.input}
                  value={passwordInput}
                  onChange={(e) => setPasswordInput(e.target.value)}
                  onKeyDown={(e) => { if (e.key === "Enter") intentarDesbloquear(); }}
                  autoFocus
                />
              </Field>
            </div>
            <div style={styles.modalFooter}>
              <div style={{ flex: 1 }} />
              <button type="button" style={styles.btnGhost} onClick={() => setModalPassword(false)}>Cancelar</button>
              <button type="button" style={styles.btnPrimary} onClick={intentarDesbloquear}>Desbloquear</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function MantenimientoTab() {
  const [tasks, setTasks] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [seq, setSeq] = useState(1);
  const [view, setView] = useState("kanban"); // kanban | lista
  const [query, setQuery] = useState("");
  const [filtroTipo, setFiltroTipo] = useState("todos");
  const [filtroPrioridad, setFiltroPrioridad] = useState("todos");
  const [fechaDesde, setFechaDesde] = useState("");
  const [fechaHasta, setFechaHasta] = useState("");
  const [ahora, setAhora] = useState(new Date());
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState(emptyForm());
  const [nuevaSubtarea, setNuevaSubtarea] = useState("");
  const [dragId, setDragId] = useState(null);
  const [mesesColapsados, setMesesColapsados] = useState(() => new Set());
  const [completadoColapsado, setCompletadoColapsado] = useState(false);
  const mesesUiCargadaRef = useRef(false);

  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(MESES_COMPLETADO_KEY, false);
        if (res && res.value) setMesesColapsados(new Set(JSON.parse(res.value)));
      } catch (e) {
        /* no existe aún */
      }
      mesesUiCargadaRef.current = true;
    })();
  }, []);

  useEffect(() => {
    if (!mesesUiCargadaRef.current) return;
    storage.set(MESES_COMPLETADO_KEY, JSON.stringify(Array.from(mesesColapsados)), false).catch(() => {});
  }, [mesesColapsados]);

  function toggleMesCompletado(clave) {
    setMesesColapsados((prev) => {
      const next = new Set(prev);
      if (next.has(clave)) next.delete(clave);
      else next.add(clave);
      return next;
    });
  }

  const [saveError, setSaveError] = useState(false);
  const [formError, setFormError] = useState("");
  const modalBodyRef = useRef(null);
  const [registros, setRegistros] = useState([]);
  const [registroForm, setRegistroForm] = useState({ equipo: "", tarea: "", tecnico: "", fecha: todayISO() });
  const [trabajos, setTrabajos] = useState([]);
  const [trabajoForm, setTrabajoForm] = useState({ equipo: "" });
  const preventivosPanelRef = useRef(null);
  const [columnasMeses, setColumnasMeses] = useState(6);
  const [mesModal, setMesModal] = useState(null); // { trabajoId, indiceMes } | null

  useEffect(() => {
    const el = preventivosPanelRef.current;
    if (!el) return;
    const calcularColumnas = (anchoDisponible) => {
      const gap = 3;
      for (const cols of [6, 4, 3, 2]) {
        const anchoCelda = (anchoDisponible - gap * (cols - 1)) / cols;
        if (anchoCelda >= 40) return cols;
      }
      return 2;
    };
    const actualizar = () => setColumnasMeses(calcularColumnas(el.clientWidth || 300));
    actualizar();
    const obs = new ResizeObserver(actualizar);
    obs.observe(el);
    return () => obs.disconnect();
  }, []);

  // ---- carga inicial ----
  const yaModificoRef = useRef(false);
  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(STORAGE_KEY, false);
        if (res && res.value && !yaModificoRef.current) {
          const originales = JSON.parse(res.value);
          const cargadas = originales.map((t) => ({
            ...t,
            ot: t.ot && t.ot.startsWith("OT-") ? t.ot.replace("OT-", "Tarea N° ") : t.ot,
            estado: (t.estado === "programado" || t.estado === "en_proceso") ? "pendiente" : t.estado,
          }));
          setTasks(cargadas);
          const huboMigracion = cargadas.some(
            (t, i) => t.ot !== originales[i].ot || t.estado !== originales[i].estado
          );
          if (huboMigracion) {
            storage.set(STORAGE_KEY, JSON.stringify(cargadas), false).catch(() => {});
          }
        }
      } catch (e) {
        /* no existe aún */
      }
      try {
        const res2 = await storage.get(SEQ_KEY, false);
        if (res2 && res2.value && !yaModificoRef.current) setSeq(JSON.parse(res2.value));
      } catch (e) {
        /* no existe aún */
      }
      try {
        const res4 = await storage.get(REGISTROS_KEY, false);
        if (res4 && res4.value && !yaModificoRef.current) setRegistros(JSON.parse(res4.value));
      } catch (e) {
        /* no existe aún */
      }
      try {
        const res5 = await storage.get(TRABAJOS_KEY, false);
        if (res5 && res5.value && !yaModificoRef.current) {
          const cargados = JSON.parse(res5.value).map((tr) => {
            if (!Array.isArray(tr.meses)) {
              // migración: equipos viejos sin el arreglo de 12 meses
              return { id: tr.id, equipo: tr.equipo, meses: MESES_ANIO.map((_, i) => ({ mes: i + 1, estado: "vacio", fecha: "", proveedor: "" })) };
            }
            // migración: meses con el modelo viejo (booleano "hecho") al nuevo de 3 estados
            return {
              ...tr,
              meses: tr.meses.map((m) => {
                if (m.estado) return { proveedor: "", ...m };
                return { mes: m.mes, estado: m.hecho ? "hecho" : "vacio", fecha: m.fecha || "", proveedor: m.proveedor || "" };
              }),
            };
          });
          setTrabajos(cargados);
        }
      } catch (e) {
        /* no existe aún */
      }
      setLoaded(true);
    })();
  }, []);

  // ---- reloj en vivo ----
  useEffect(() => {
    const id = setInterval(() => setAhora(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  const fechaHoyTexto = ahora.toLocaleDateString("es-AR", {
    weekday: "long", day: "numeric", month: "long", year: "numeric",
  });
  const horaActualTexto = ahora.toLocaleTimeString("es-AR", {
    hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false,
  });

  // ---- persistencia ----
  const persist = async (next, nextSeq) => {
    try {
      const r1 = await storage.set(STORAGE_KEY, JSON.stringify(next), false);
      if (!r1) throw new Error("fail");
      if (nextSeq !== undefined) {
        await storage.set(SEQ_KEY, JSON.stringify(nextSeq), false);
      }
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  };

  const otNumber = (n) => `Tarea N° ${String(n).padStart(4, "0")}`;

  // guarda la fecha de completado al pasar a "completado" y la borra si sale de ese estado
  function aplicarFechaCompletado(t, nuevoEstado) {
    if (nuevoEstado === "completado") {
      return { ...t, estado: nuevoEstado, fechaCompletado: t.fechaCompletado || todayISO() };
    }
    return { ...t, estado: nuevoEstado, fechaCompletado: null };
  }

  function openNuevo() {
    setForm(emptyForm());
    setNuevaSubtarea("");
    setFormError("");
    setModalOpen(true);
  }
  function openEditar(t) {
    setForm({ subtareas: [], ...t });
    setNuevaSubtarea("");
    setFormError("");
    setModalOpen(true);
  }

  function agregarSubtarea() {
    const texto = nuevaSubtarea.trim();
    if (!texto) return;
    setForm({
      ...form,
      subtareas: [...(form.subtareas || []), { id: uid(), texto, hecho: false, fechaHecho: null }],
    });
    setNuevaSubtarea("");
  }

  function editarTextoSubtarea(id, texto) {
    setForm({
      ...form,
      subtareas: (form.subtareas || []).map((s) => (s.id === id ? { ...s, texto } : s)),
    });
  }

  function toggleSubtareaForm(id) {
    const subtareasActualizadas = (form.subtareas || []).map((s) => {
      if (s.id !== id) return s;
      const nuevoHecho = !s.hecho;
      return { ...s, hecho: nuevoHecho, fechaHecho: nuevoHecho ? todayISO() : null };
    });
    const todasHechas = subtareasActualizadas.length > 0 && subtareasActualizadas.every((s) => s.hecho);
    if (todasHechas && form.estado !== "completado") {
      setForm(aplicarFechaCompletado({ ...form, subtareas: subtareasActualizadas }, "completado"));
    } else {
      setForm({ ...form, subtareas: subtareasActualizadas });
    }
  }

  function eliminarSubtareaForm(id) {
    setForm({
      ...form,
      subtareas: (form.subtareas || []).filter((s) => s.id !== id),
    });
  }

  // toggle rápido de subtarea directamente desde la tarjeta, sin abrir el modal
  function toggleSubtareaDirecta(taskId, subId) {
    const next = tasks.map((t) => {
      if (t.id !== taskId) return t;
      const subtareasActualizadas = (t.subtareas || []).map((s) => {
        if (s.id !== subId) return s;
        const nuevoHecho = !s.hecho;
        return { ...s, hecho: nuevoHecho, fechaHecho: nuevoHecho ? todayISO() : null };
      });
      const todasHechas = subtareasActualizadas.length > 0 && subtareasActualizadas.every((s) => s.hecho);
      if (todasHechas && t.estado !== "completado") {
        return aplicarFechaCompletado({ ...t, subtareas: subtareasActualizadas }, "completado");
      }
      return { ...t, subtareas: subtareasActualizadas };
    });
    setTasks(next);
    persist(next);
  }

  function guardarForm(e) {
    if (e && e.preventDefault) e.preventDefault();
    if (!form.titulo.trim() || !form.equipo.trim()) {
      setFormError(
        !form.titulo.trim()
          ? "Falta el título de la tarea."
          : "Falta el equipo / activo."
      );
      if (modalBodyRef.current) modalBodyRef.current.scrollTop = 0;
      return;
    }
    setFormError("");
    yaModificoRef.current = true;

    if (form.id) {
      const next = tasks.map((t) =>
        t.id === form.id ? aplicarFechaCompletado({ ...form }, form.estado) : t
      );
      setTasks(next);
      persist(next);
    } else {
      const base = { ...form, id: uid(), ot: otNumber(seq), createdAt: Date.now(), fechaCompletado: null };
      const nuevo = aplicarFechaCompletado(base, form.estado);
      const next = [nuevo, ...tasks];
      const nextSeq = seq + 1;
      setTasks(next);
      setSeq(nextSeq);
      persist(next, nextSeq);
    }
    setModalOpen(false);
  }

  function eliminar(id) {
    const next = tasks.filter((t) => t.id !== id);
    setTasks(next);
    persist(next);
  }

  // ---- registros faltantes (lista simple aparte de las tareas) ----
  const persistRegistros = async (next) => {
    try {
      const r = await storage.set(REGISTROS_KEY, JSON.stringify(next), false);
      if (!r) throw new Error("fail");
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  };

  function agregarRegistro() {
    if (!registroForm.equipo.trim() || !registroForm.tarea.trim()) return;
    yaModificoRef.current = true;
    const nuevo = {
      id: uid(),
      equipo: registroForm.equipo.trim(),
      tarea: registroForm.tarea.trim(),
      tecnico: registroForm.tecnico.trim(),
      fecha: registroForm.fecha || todayISO(),
    };
    const next = [nuevo, ...registros];
    setRegistros(next);
    persistRegistros(next);
    setRegistroForm({ equipo: "", tarea: "", tecnico: "", fecha: todayISO() });
  }

  function eliminarRegistro(id) {
    const next = registros.filter((r) => r.id !== id);
    setRegistros(next);
    persistRegistros(next);
  }

  // ---- Trabajos No Rutinarios (tarjetas con 3 estados fijos tildables) ----
  const persistTrabajos = async (next) => {
    try {
      const r = await storage.set(TRABAJOS_KEY, JSON.stringify(next), false);
      if (!r) throw new Error("fail");
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  };

  function agregarTrabajo() {
    if (!trabajoForm.equipo.trim()) return;
    yaModificoRef.current = true;
    const nuevo = {
      id: uid(),
      equipo: trabajoForm.equipo.trim(),
      meses: MESES_ANIO.map((_, i) => ({ mes: i + 1, estado: "vacio", fecha: "", proveedor: "" })),
    };
    const next = [nuevo, ...trabajos];
    setTrabajos(next);
    persistTrabajos(next);
    setTrabajoForm({ equipo: "" });
  }

  function eliminarTrabajo(id) {
    const next = trabajos.filter((tr) => tr.id !== id);
    setTrabajos(next);
    persistTrabajos(next);
  }

  function actualizarEquipoTrabajo(id, nombre) {
    const next = trabajos.map((tr) => (tr.id === id ? { ...tr, equipo: nombre } : tr));
    setTrabajos(next);
    persistTrabajos(next);
  }

  function actualizarMesTrabajo(trabajoId, indiceMes, cambios) {
    const next = trabajos.map((tr) => {
      if (tr.id !== trabajoId) return tr;
      return {
        ...tr,
        meses: tr.meses.map((m, i) => (i === indiceMes ? { ...m, ...cambios } : m)),
      };
    });
    setTrabajos(next);
    persistTrabajos(next);
  }

  function rotarEstadoMes(trabajoId, indiceMes) {
    const tr = trabajos.find((t) => t.id === trabajoId);
    const m = tr && tr.meses[indiceMes];
    if (!m) return;
    const siguiente = m.estado === "vacio" ? "hecho" : m.estado === "hecho" ? "anulado" : "vacio";
    actualizarMesTrabajo(trabajoId, indiceMes, {
      estado: siguiente,
      fecha: siguiente === "hecho" ? (m.fecha || todayISO()) : m.fecha,
    });
  }

  function moverEstado(id, estado) {
    const next = tasks.map((t) => (t.id === id ? aplicarFechaCompletado(t, estado) : t));
    setTasks(next);
    persist(next);
  }

  const filtradas = useMemo(() => {
    return tasks.filter((t) => {
      if (filtroTipo !== "todos" && t.tipo !== filtroTipo) return false;
      if (filtroPrioridad !== "todos" && t.prioridad !== filtroPrioridad) return false;
      if (fechaDesde && (!t.fecha || t.fecha < fechaDesde)) return false;
      if (fechaHasta && (!t.fecha || t.fecha > fechaHasta)) return false;
      if (query.trim()) {
        const q = query.toLowerCase();
        const hay =
          t.titulo.toLowerCase().includes(q) ||
          t.equipo.toLowerCase().includes(q) ||
          (t.tecnico || "").toLowerCase().includes(q) ||
          (t.ot || "").toLowerCase().includes(q);
        if (!hay) return false;
      }
      return true;
    });
  }, [tasks, filtroTipo, filtroPrioridad, fechaDesde, fechaHasta, query]);

  const stats = useMemo(() => {
    const total = tasks.length;
    const vencidas = tasks.filter(isOverdue).length;
    const porEstado = {};
    ESTADOS.forEach((e) => (porEstado[e.id] = tasks.filter((t) => t.estado === e.id).length));
    return { total, vencidas, porEstado };
  }, [tasks]);

  return (
    <>
      <div style={styles.headerToolbar}>
        {/* Header */}
        <header style={styles.header}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ ...styles.logoBadge, background: "#FFFFFF" }}>
              <img src={ICONO_MANTENIMIENTO} alt="" style={styles.logoBadgeImg} />
            </div>
            <div>
              <div style={styles.h1}>PLANIFICADOR DE MANTENIMIENTO</div>
              <div style={styles.sub}>Tareas de mantenimiento · Programación · Seguimiento</div>
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
            <div style={styles.clockBox}>
              <div style={styles.clockDate}>{fechaHoyTexto}</div>
              <div style={styles.clockTime}>{horaActualTexto}</div>
            </div>
            <button style={{ ...styles.btnPrimary, opacity: loaded ? 1 : 0.5, cursor: loaded ? "pointer" : "not-allowed" }} onClick={openNuevo} disabled={!loaded}>
              <Plus size={16} /> {loaded ? "Nueva Tarea" : "Cargando..."}
            </button>
          </div>
        </header>

        {saveError && (
          <div style={styles.errorBar}>
            No se pudo guardar. Los cambios podrían perderse — reintenta la acción.
          </div>
        )}

        {/* Stats */}
        <div style={styles.statsRow}>
          <StatChip label="Total tareas" value={stats.total} color="var(--text-dim)" />
          {ESTADOS.map((e) => (
            <StatChip key={e.id} label={e.label} value={stats.porEstado[e.id] || 0} color={e.color} />
          ))}
          <StatChip label="Vencidas" value={stats.vencidas} color="#C1554A" alert={stats.vencidas > 0} />
        </div>

        {/* Controls */}
        <div style={{ ...styles.controls }} className="top-controls">
          <div style={styles.searchBox}>
            <Search size={15} color="var(--text-dim)" />
            <input
              style={styles.searchInput}
              placeholder="Buscar por N° de tarea, equipo, título o técnico..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
            />
          </div>
          <FilterSelect
            icon={<Tag size={13} />}
            value={filtroTipo}
            onChange={setFiltroTipo}
            options={[{ id: "todos", label: "Todos los tipos" }, ...TIPOS]}
          />
          <FilterSelect
            icon={<AlertTriangle size={13} />}
            value={filtroPrioridad}
            onChange={setFiltroPrioridad}
            options={[{ id: "todos", label: "Toda prioridad" }, ...PRIORIDADES]}
          />
          <div style={styles.dateFilterBox}>
            <Calendar size={13} color="var(--text-dim)" />
            <input
              type="date"
              style={styles.dateFilterInput}
              value={fechaDesde}
              onChange={(e) => setFechaDesde(e.target.value)}
              title="Desde"
            />
            <span style={{ color: "var(--text-dim)", fontSize: 12 }}>–</span>
            <input
              type="date"
              style={styles.dateFilterInput}
              value={fechaHasta}
              onChange={(e) => setFechaHasta(e.target.value)}
              title="Hasta"
            />
            {(fechaDesde || fechaHasta) && (
              <button
                style={styles.dateFilterClear}
                onClick={() => { setFechaDesde(""); setFechaHasta(""); }}
                title="Limpiar filtro de fechas"
              >
                <X size={13} />
              </button>
            )}
          </div>
          <div style={styles.viewToggle}>
            <button
              style={{ ...styles.viewBtn, ...(view === "kanban" ? styles.viewBtnActive : {}) }}
              onClick={() => setView("kanban")}
              title="Vista tablero"
            >
              <LayoutGrid size={15} />
            </button>
            <button
              style={{ ...styles.viewBtn, ...(view === "lista" ? styles.viewBtnActive : {}) }}
              onClick={() => setView("lista")}
              title="Vista lista"
            >
              <ListIcon size={15} />
            </button>
          </div>
        </div>
      </div>

      {/* Body */}
      <div style={styles.mainGrid} className="scrollbar main-grid">
      {!loaded ? (
        <div style={{ ...styles.emptyState, gridColumn: "1 / span 2" }}>Cargando tareas…</div>
      ) : view === "kanban" ? (
        ESTADOS.filter((estado) => estado.id === "pendiente").map((estado) => (
          <div
            key={estado.id}
            style={{ ...styles.col, gridColumn: "1 / span 2" }}
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => {
              if (dragId) moverEstado(dragId, estado.id);
              setDragId(null);
            }}
          >
            <div style={styles.colHeader}>
              <span style={{ ...styles.dot, background: estado.color }} />
              <span style={styles.colTitle}>{estado.label}</span>
              <span style={styles.colCount}>
                {filtradas.filter((t) => t.estado === estado.id).length}
              </span>
            </div>
            <div style={styles.colBody} className="scrollbar">
              <>
                {filtradas
                  .filter((t) => t.estado === estado.id)
                  .map((t) => (
                    <TaskCard
                      key={t.id}
                      t={t}
                      onEdit={() => openEditar(t)}
                      onDelete={() => eliminar(t.id)}
                      onDragStart={() => setDragId(t.id)}
                      onToggleSubtarea={(subId) => toggleSubtareaDirecta(t.id, subId)}
                    />
                  ))}
                {filtradas.filter((t) => t.estado === estado.id).length === 0 && (
                  <div style={styles.colEmpty}>Sin tareas aquí</div>
                )}
              </>
            </div>
          </div>
        ))
      ) : (
        <div style={{ ...styles.listWrap, gridColumn: "1 / span 2" }} className="scrollbar">
          {filtradas.length === 0 ? (
            <div style={styles.emptyState}>No hay tareas que coincidan.</div>
          ) : (
            <table style={styles.table}>
              <thead>
                <tr>
                  {["Tarea N°", "Título", "Equipo", "Tipo", "Prioridad", "Técnico", "Fecha", "Estado", ""].map((h) => (
                    <th key={h} style={styles.th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {filtradas.map((t) => {
                  const pr = PRIORIDADES.find((p) => p.id === t.prioridad);
                  const es = ESTADOS.find((e) => e.id === t.estado);
                  const venc = isOverdue(t);
                  return (
                    <tr key={t.id} style={styles.tr}>
                      <td style={{ ...styles.td, fontFamily: "Arial, Helvetica, sans-serif", color: "var(--accent)" }}>{t.ot}</td>
                      <td style={styles.td}>{t.titulo}</td>
                      <td style={{ ...styles.td, color: "var(--text-dim)" }}>{t.equipo}</td>
                      <td style={styles.td}>{TIPOS.find((x) => x.id === t.tipo)?.label}</td>
                      <td style={styles.td}>
                        <Pill color={pr?.color}>{pr?.label}</Pill>
                      </td>
                      <td style={styles.td}>{t.tecnico || "—"}</td>
                      <td style={{ ...styles.td, color: venc ? "#C1554A" : "var(--text-dim)" }}>
                        {fmtDate(t.fecha)} {venc && "· vencida"}
                      </td>
                      <td style={styles.td}>
                        <select
                          value={t.estado}
                          onChange={(e) => moverEstado(t.id, e.target.value)}
                          style={styles.inlineSelect}
                        >
                          {ESTADOS.map((e) => (
                            <option key={e.id} value={e.id}>{e.label}</option>
                          ))}
                        </select>
                      </td>
                      <td style={styles.td}>
                        <div style={{ display: "flex", gap: 6 }}>
                          <IconBtn onClick={() => openEditar(t)}><Pencil size={13} /></IconBtn>
                          <IconBtn onClick={() => eliminar(t.id)} danger><Trash2 size={13} /></IconBtn>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      )}

      <div style={styles.dividerLine} className="divider-line" />

      {/* Panel de Completado, agrupado por mes */}
      <div style={styles.registrosPanel}>
        <div
          style={{ ...styles.registrosHeader, cursor: "pointer" }}
          onClick={() => setCompletadoColapsado((c) => !c)}
        >
          <ChevronDown
            size={14}
            color="var(--text-dim)"
            style={{ transform: completadoColapsado ? "rotate(-90deg)" : "none", transition: "transform .15s" }}
          />
          <span style={{ ...styles.dot, background: "#6FA97A" }} />
          <span style={styles.colTitle}>Completado</span>
          <span style={styles.colCount}>
            {filtradas.filter((t) => t.estado === "completado").length}
          </span>
        </div>

        {!completadoColapsado && (
          <div style={styles.colBody} className="scrollbar">
            {(() => {
              const tareasCompletadas = filtradas.filter((t) => t.estado === "completado");
              if (tareasCompletadas.length === 0) {
                return <div style={styles.colEmpty}>Sin tareas aquí</div>;
              }
              const gruposPorClave = {};
              tareasCompletadas.forEach((t) => {
                const clave = claveMes(t.fechaCompletado || t.fecha);
                if (!gruposPorClave[clave]) gruposPorClave[clave] = [];
                gruposPorClave[clave].push(t);
              });
              const clavesOrdenadas = Object.keys(gruposPorClave).sort((a, b) => (a < b ? 1 : a > b ? -1 : 0));
              return clavesOrdenadas.map((clave) => {
                const tareasDelMes = gruposPorClave[clave];
                const colapsado = mesesColapsados.has(clave);
                return (
                  <div key={clave} style={styles.mesGrupo}>
                    <div style={styles.mesGrupoHeader} onClick={() => toggleMesCompletado(clave)}>
                      <ChevronDown
                        size={13}
                        color="var(--text-dim)"
                        style={{ transform: colapsado ? "rotate(-90deg)" : "none", transition: "transform .15s" }}
                      />
                      <span style={styles.mesGrupoTitulo}>{etiquetaMes(clave)}</span>
                      <span style={styles.colCount}>{tareasDelMes.length}</span>
                    </div>
                    {!colapsado && (
                      <div style={{ display: "flex", flexDirection: "column", gap: 8, marginTop: 8 }}>
                        {tareasDelMes.map((t) => (
                          <TaskCard
                            key={t.id}
                            t={t}
                            onEdit={() => openEditar(t)}
                            onDelete={() => eliminar(t.id)}
                            onDragStart={() => setDragId(t.id)}
                            onToggleSubtarea={(subId) => toggleSubtareaDirecta(t.id, subId)}
                          />
                        ))}
                      </div>
                    )}
                  </div>
                );
              });
            })()}
          </div>
        )}
      </div>

      {/* Panel de Preventivos mensuales externos (antes "TNR") */}
      <div style={styles.registrosPanel} ref={preventivosPanelRef}>
        <div style={styles.registrosHeader}>
          <span style={{ ...styles.dot, background: "#8C7BC4" }} />
          <span style={styles.colTitle}>Preventivos mensuales externos</span>
          <span style={styles.colCount}>{trabajos.length}</span>
        </div>

        <div style={styles.registroAddBox}>
          <div style={{ display: "flex", gap: 6 }}>
            <input
              style={styles.inputSmall}
              placeholder="Sistema/Equipo"
              value={trabajoForm.equipo}
              onChange={(e) => setTrabajoForm({ ...trabajoForm, equipo: e.target.value })}
              onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); agregarTrabajo(); } }}
            />
            <button type="button" style={{ ...styles.btnPrimary, padding: "0 12px" }} onClick={agregarTrabajo} title="Agregar equipo">
              <Plus size={15} />
            </button>
          </div>
        </div>

        <div style={styles.registrosList} className="scrollbar">
          {trabajos.length === 0 && (
            <div style={styles.colEmpty}>No hay equipos cargados</div>
          )}
          {trabajos.map((tr) => (
            <div key={tr.id} style={styles.registroCard}>
              <div style={styles.registroTop}>
                <div style={{ ...styles.registroEquipo, flex: 1, display: "flex", alignItems: "center", gap: 4 }}>
                  <Wrench size={11} style={{ flexShrink: 0 }} />
                  <input
                    value={tr.equipo}
                    onChange={(e) => actualizarEquipoTrabajo(tr.id, e.target.value)}
                    style={styles.trabajoEquipoInput}
                  />
                </div>
                <button
                  style={styles.subtaskDelete}
                  onClick={() => eliminarTrabajo(tr.id)}
                  title="Eliminar equipo"
                >
                  <Trash2 size={13} />
                </button>
              </div>
              <div style={{ ...styles.trabajoMesesGrid, gridTemplateColumns: `repeat(${columnasMeses}, 1fr)` }}>
                {tr.meses.map((m, i) => (
                  <div key={m.mes} style={styles.trabajoMesCelda}>
                    <span
                      onClick={() => setMesModal({ trabajoId: tr.id, indiceMes: i })}
                      title="Ver/editar fecha y proveedor"
                      style={{
                        fontSize: 10, fontWeight: 700, cursor: "pointer",
                        color: m.estado === "hecho" ? "#6FA97A" : m.estado === "anulado" ? "#7F7F7F" : "var(--text-dim)",
                        textDecoration: "underline", textDecorationStyle: "dotted",
                      }}
                    >
                      {MESES_ANIO[i]}
                    </span>
                    <button
                      type="button"
                      onClick={() => rotarEstadoMes(tr.id, i)}
                      title={
                        m.estado === "hecho" ? "Realizado — click para anular"
                        : m.estado === "anulado" ? "Anulado (no aplica este mes) — click para limpiar"
                        : "Sin marcar — click para tildar"
                      }
                      style={{
                        ...styles.trabajoMesCheck,
                        background: m.estado === "hecho" ? "#6FA97A" : m.estado === "anulado" ? "#7F7F7F33" : "var(--panel-2)",
                        borderColor: m.estado === "hecho" ? "#6FA97A" : m.estado === "anulado" ? "#7F7F7F" : "var(--border)",
                      }}
                    >
                      {m.estado === "hecho" && <CheckCircle2 size={11} color="#1B1E21" />}
                      {m.estado === "anulado" && <Minus size={11} color="#7F7F7F" style={{ transform: "rotate(45deg)" }} />}
                    </button>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      </div>

      {/* Popup de detalle de mes (fecha + proveedor) en Preventivos mensuales externos */}
      {mesModal && (() => {
        const tr = trabajos.find((t) => t.id === mesModal.trabajoId);
        const m = tr && tr.meses[mesModal.indiceMes];
        if (!tr || !m) return null;
        return (
          <div style={styles.overlay} onMouseDown={(e) => { if (e.target === e.currentTarget) setMesModal(null); }}>
            <div style={{ ...styles.modal, maxWidth: 340 }}>
              <div style={styles.modalHeader}>
                <span style={styles.modalTitle}>{tr.equipo} · {MESES_ANIO[mesModal.indiceMes]}</span>
                <button type="button" style={styles.iconClose} onClick={() => setMesModal(null)}>
                  <X size={16} />
                </button>
              </div>
              <div style={styles.modalBody}>
                <Field label="Estado">
                  <div style={{ display: "flex", gap: 8 }}>
                    {[
                      { id: "vacio", label: "Sin marcar", color: "#9AA0A6" },
                      { id: "hecho", label: "Realizado", color: "#6FA97A" },
                      { id: "anulado", label: "Anulado", color: "#7F7F7F" },
                    ].map((op) => (
                      <button
                        key={op.id}
                        type="button"
                        onClick={() => actualizarMesTrabajo(tr.id, mesModal.indiceMes, {
                          estado: op.id,
                          fecha: op.id === "hecho" ? (m.fecha || todayISO()) : m.fecha,
                        })}
                        style={{
                          flex: 1, padding: "8px 0", borderRadius: 6, cursor: "pointer",
                          border: m.estado === op.id ? `2px solid ${op.color}` : "1px solid var(--border)",
                          background: m.estado === op.id ? `${op.color}33` : "var(--panel)",
                          color: "var(--text)", fontWeight: 700, fontSize: 11.5,
                        }}
                      >
                        {op.label}
                      </button>
                    ))}
                  </div>
                </Field>
                <Field label="Fecha">
                  <input
                    type="date"
                    style={styles.input}
                    value={m.fecha}
                    onChange={(e) => actualizarMesTrabajo(tr.id, mesModal.indiceMes, { fecha: e.target.value })}
                  />
                </Field>
                <Field label="Proveedor">
                  <input
                    type="text"
                    style={styles.input}
                    placeholder="Quién realizó el trabajo"
                    value={m.proveedor || ""}
                    onChange={(e) => actualizarMesTrabajo(tr.id, mesModal.indiceMes, { proveedor: e.target.value })}
                  />
                </Field>
              </div>
              <div style={styles.modalFooter}>
                <div style={{ flex: 1 }} />
                <button type="button" style={styles.btnPrimary} onClick={() => setMesModal(null)}>Listo</button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* Modal */}
      {modalOpen && (
        <div style={styles.overlay} onMouseDown={(e) => { if (e.target === e.currentTarget) setModalOpen(false); }}>
          <div style={styles.modal}>
            <div style={styles.modalHeader}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <ClipboardList size={16} color="var(--accent)" />
                <span style={styles.modalTitle}>
                  {form.id ? `Editar ${form.ot}` : "Nueva tarea"}
                </span>
              </div>
              <button type="button" style={styles.iconClose} onClick={() => setModalOpen(false)}>
                <X size={16} />
              </button>
            </div>

            <div style={styles.modalBody} className="scrollbar" ref={modalBodyRef}>
              {formError && (
                <div style={styles.formErrorBanner}>
                  <AlertTriangle size={14} /> {formError}
                </div>
              )}
              <Field label="Título de la tarea *">
                <input
                  style={{ ...styles.input, ...(formError && !form.titulo.trim() ? styles.inputError : {}) }}
                  value={form.titulo}
                  onChange={(e) => setForm({ ...form, titulo: e.target.value })}
                  onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); guardarForm(); } }}
                  placeholder="Ej: Cambio de rodamientos motor principal"
                />
              </Field>

              <Field label="Equipo / activo *">
                <input
                  style={{ ...styles.input, ...(formError && !form.equipo.trim() ? styles.inputError : {}) }}
                  value={form.equipo}
                  onChange={(e) => setForm({ ...form, equipo: e.target.value })}
                  onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); guardarForm(); } }}
                  placeholder="Ej: Bomba centrífuga P-102"
                />
              </Field>

              <div style={styles.row2}>
                <Field label="Tipo de mantenimiento">
                  <select style={styles.input} value={form.tipo} onChange={(e) => setForm({ ...form, tipo: e.target.value })}>
                    {TIPOS.map((t) => <option key={t.id} value={t.id}>{t.label}</option>)}
                  </select>
                </Field>
                <Field label="Prioridad">
                  <select style={styles.input} value={form.prioridad} onChange={(e) => setForm({ ...form, prioridad: e.target.value })}>
                    {PRIORIDADES.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
                  </select>
                </Field>
              </div>

              <div style={styles.row2}>
                <Field label="Técnico asignado">
                  <input
                    style={styles.input}
                    value={form.tecnico}
                    onChange={(e) => setForm({ ...form, tecnico: e.target.value })}
                    placeholder="Nombre del técnico"
                  />
                </Field>
                <Field label="Fecha programada">
                  <input
                    type="date"
                    style={styles.input}
                    value={form.fecha}
                    onChange={(e) => setForm({ ...form, fecha: e.target.value })}
                  />
                </Field>
              </div>

              <Field label="Estado">
                <select style={styles.input} value={form.estado} onChange={(e) => setForm({ ...form, estado: e.target.value })}>
                  {ESTADOS.map((e) => <option key={e.id} value={e.id}>{e.label}</option>)}
                </select>
                {form.estado === "completado" && form.fechaCompletado && (
                  <span style={styles.completedInline}>
                    <CheckCircle2 size={12} /> Completada el {fmtDate(form.fechaCompletado)}
                  </span>
                )}
              </Field>

              <Field label="Descripción / notas técnicas">
                <textarea
                  style={{ ...styles.input, minHeight: 80, resize: "vertical" }}
                  value={form.descripcion}
                  onChange={(e) => setForm({ ...form, descripcion: e.target.value })}
                  placeholder="Detalle del trabajo, repuestos requeridos, observaciones..."
                />
              </Field>

              <Field label={`Subtareas ${form.subtareas && form.subtareas.length ? `(${form.subtareas.filter((s) => s.hecho).length}/${form.subtareas.length})` : ""}`}>
                {form.subtareas && form.subtareas.length > 0 && (
                  <div style={styles.progressTrack}>
                    <div
                      style={{
                        ...styles.progressFill,
                        width: `${(form.subtareas.filter((s) => s.hecho).length / form.subtareas.length) * 100}%`,
                        background: form.subtareas.every((s) => s.hecho) ? "#6FA97A" : "var(--accent)",
                      }}
                    />
                  </div>
                )}
                <div style={styles.subtaskList}>
                  {(form.subtareas || []).length === 0 && (
                    <div style={styles.subtaskEmpty}>Todavía no agregaste subtareas.</div>
                  )}
                  {(form.subtareas || []).map((s) => (
                    <div key={s.id} style={styles.subtaskRow}>
                      <input
                        type="checkbox"
                        checked={s.hecho}
                        onChange={() => toggleSubtareaForm(s.id)}
                        style={{ ...styles.checkbox, accentColor: s.hecho ? "#6FA97A" : "var(--accent)" }}
                      />
                      <input
                        style={{
                          ...styles.subtaskInput,
                          textDecoration: s.hecho ? "line-through" : "none",
                          color: s.hecho ? "var(--text-dim)" : "var(--text)",
                        }}
                        value={s.texto}
                        onChange={(e) => editarTextoSubtarea(s.id, e.target.value)}
                      />
                      {s.hecho && s.fechaHecho && (
                        <span style={styles.subtaskDate}>{fmtDate(s.fechaHecho)}</span>
                      )}
                      <button
                        type="button"
                        style={styles.subtaskDelete}
                        onClick={() => eliminarSubtareaForm(s.id)}
                        title="Eliminar subtarea"
                      >
                        <X size={13} />
                      </button>
                    </div>
                  ))}
                </div>
                <div style={styles.subtaskAddRow}>
                  <input
                    style={styles.input}
                    placeholder="Agregar subtarea y presionar Enter"
                    value={nuevaSubtarea}
                    onChange={(e) => setNuevaSubtarea(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        agregarSubtarea();
                      }
                    }}
                  />
                  <button type="button" style={styles.btnGhost} onClick={agregarSubtarea}>
                    <Plus size={14} />
                  </button>
                </div>
              </Field>
            </div>

            <div style={styles.modalFooter}>
              {form.id && (
                <button
                  type="button"
                  style={styles.btnDanger}
                  onClick={() => { eliminar(form.id); setModalOpen(false); }}
                >
                  <Trash2 size={14} /> Eliminar
                </button>
              )}
              <div style={{ flex: 1 }} />
              <button type="button" style={styles.btnGhost} onClick={() => setModalOpen(false)}>Cancelar</button>
              <button type="button" style={styles.btnPrimary} onClick={guardarForm}>
                {form.id ? "Guardar cambios" : "Crear tarea"}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

