/* ---------------------- Parada de Planta ---------------------- */

const PROVEEDOR_PALETTE = ["#0088CE", "#A30050", "#E37222", "#00747A", "#693A77", "#44697D"];
const GANTT_BAR_GAP = 6; // espacio a la derecha de cada barra para que entre la flecha de dependencia

function colorForProveedor(nombre) {
  if (!nombre) return "#4A90A4";
  let hash = 0;
  for (let i = 0; i < nombre.length; i++) hash = (hash * 31 + nombre.charCodeAt(i)) >>> 0;
  return PROVEEDOR_PALETTE[hash % PROVEEDOR_PALETTE.length];
}

// Rellena con valores por defecto las subtareas creadas antes de tener
// fechas/porcentaje/dependencias propias, para no romper datos viejos.
function migrarSubtarea(s, fechaBase) {
  return {
    ...s,
    fechaInicio: s.fechaInicio || fechaBase,
    fechaFin: s.fechaFin || fechaBase,
    porcentaje: s.porcentaje !== undefined ? s.porcentaje : (s.hecho ? 100 : 0),
    dependencias: s.dependencias || [],
  };
}

// Compara hoy contra la fecha de fin planificada para saber si la tarea
// va en tiempo, atrasada, o si terminó antes de lo previsto.
function estadoTiempoTarea(t) {
  const hoy = todayISO();
  const pct = Math.max(0, Math.min(100, t.porcentaje || 0));
  if (pct >= 100) {
    const diasAntes = diffDias(t.fechaFin, hoy);
    if (diasAntes > 0) {
      return { texto: `Finalizada ${diasAntes} día${diasAntes !== 1 ? "s" : ""} antes`, color: "#6FA97A" };
    }
    return { texto: "Finalizada en tiempo", color: "#6FA97A" };
  }
  const diasAtraso = diffDias(hoy, t.fechaFin);
  if (diasAtraso > 0) {
    return { texto: `Atrasada ${diasAtraso} día${diasAtraso !== 1 ? "s" : ""}`, color: "var(--accent)" };
  }
  return { texto: "En tiempo", color: "#6FA97A" };
}

// Normaliza texto para comparar/agrupar secciones sin que las diferencias de
// mayúsculas/minúsculas o tildes generen grupos separados.
function normalizarTexto(s) {
  return (s || "")
    .toString()
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

// Cualquier sección que mencione "fracción A" (con o sin tilde, mayúsculas,
// o texto adicional alrededor) se agrupa bajo un único sector canónico.
function canonicalizarSector(sector) {
  const norm = normalizarTexto(sector);
  if (norm.includes("fraccion a")) return "Fracción A";
  if (norm.includes("cocina") || norm.includes("lavavajillas")) return "Cocina";
  if (norm.includes("lavadero") || norm.includes("deposito 5")) return "Lavadero";
  if (norm.includes("fraccion b")) return "Fracción B";
  return sector;
}

function diffDias(aISO, bISO) {
  return Math.round((new Date(aISO + "T00:00:00") - new Date(bISO + "T00:00:00")) / 86400000);
}

function sumarDias(iso, n) {
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}

// Paleta de estados para las celdas del Cronograma de parada e inicio.
// El click sobre una celda va rotando en este mismo orden.
const CRONOGRAMA_ESTADOS = [
  { id: "vacio", color: "var(--panel)", texto: "", label: "Vacío" },
  { id: "gris", color: "#BFBFBF", texto: "", label: "Gris (sin actividad / no aplica)" },
  { id: "grisOscuro", color: "#7F7F7F", texto: "", label: "Gris oscuro (fin de semana)" },
  { id: "amarillo", color: "#FFF176", texto: "", label: "Amarillo (operando)" },
  { id: "rojo", color: "#E53935", texto: "", label: "Rojo — primer/último día de operación" },
  { id: "limpieza", color: "#F5A623", texto: "LIMP.", label: "Naranja — limpieza de equipos/sector" },
  { id: "liberacion", color: "#43A047", texto: "LIB", label: "Verde — liberación del sector" },
  { id: "celeste", color: "#90CAF9", texto: "", label: "Celeste" },
];

const DIAS_SEMANA_LETRA = ["D", "L", "M", "M", "J", "V", "S"];

function letraDia(fechaISO) {
  const d = new Date(fechaISO + "T00:00:00");
  return DIAS_SEMANA_LETRA[d.getDay()];
}

// Dependencia fin→inicio: la tarea dependiente arranca el mismo día en que
// termina la tarea de la que depende (si depende de varias, la más tardía).
// Se aplica en cadena para que los cambios se propaguen a toda la secuencia.
function recalcularDependencias(lista) {
  let resultado = lista.map((t) => ({ ...t }));
  let cambiado = true;
  let vueltas = 0;
  while (cambiado && vueltas < resultado.length + 2) {
    cambiado = false;
    const porId = {};
    resultado.forEach((t) => { porId[t.id] = t; });
    resultado = resultado.map((t) => {
      if (!t.dependencias || t.dependencias.length === 0) return t;
      const fechasFin = t.dependencias.map((id) => porId[id]?.fechaFin).filter(Boolean);
      if (fechasFin.length === 0) return t;
      const maxFin = fechasFin.reduce((a, b) => (b > a ? b : a));
      const inicioEsperado = sumarDias(maxFin, 1);
      if (t.fechaInicio !== inicioEsperado) {
        const duracion = Math.max(diffDias(t.fechaFin, t.fechaInicio), 0);
        cambiado = true;
        return { ...t, fechaInicio: inicioEsperado, fechaFin: sumarDias(inicioEsperado, duracion) };
      }
      return t;
    });
    vueltas++;
  }
  return resultado;
}

