                        position: "absolute",
                        top: top + fila.height / 2 - 4,
                        left,
                        width: Math.max(width - GANTT_BAR_GAP, 8),
                        height: 8,
                        borderRadius: 4,
                        cursor: "pointer",
                        overflow: "hidden",
                        background: "var(--border)",
                        boxShadow: "0 1px 2px rgba(0,0,0,0.2)",
