function CentrifugasTab() {
  const [puntos, setPuntos] = useState([]);
  const [tanques, setTanques] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [saveError, setSaveError] = useState(false);
  const [editando, setEditando] = useState(null); // id de centrífuga en edición
  const [editandoTanque, setEditandoTanque] = useState(null); // id de tanque en edición
  const yaModificoRef = useRef(false);

  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(CENTRIFUGAS_KEY, false);
        if (res && res.value && !yaModificoRef.current) {
          setPuntos(JSON.parse(res.value));
        } else if (!yaModificoRef.current) {
          const iniciales = puntosIniciales();
          setPuntos(iniciales);
          storage.set(CENTRIFUGAS_KEY, JSON.stringify(iniciales), false).catch(() => {});
        }
      } catch (e) {
        const iniciales = puntosIniciales();
        setPuntos(iniciales);
        storage.set(CENTRIFUGAS_KEY, JSON.stringify(iniciales), false).catch(() => {});
      }
      try {
        const res2 = await storage.get(TANQUES_KEY, false);
        if (res2 && res2.value && !yaModificoRef.current) {
          let cargados = JSON.parse(res2.value);
          if (!cargados.some((t) => t.lado === "intermedio")) {
            const nuevos = tanquesIniciales().filter((t) => t.lado === "intermedio");
            cargados = [...cargados, ...nuevos];
            storage.set(TANQUES_KEY, JSON.stringify(cargados), false).catch(() => {});
          }
          setTanques(cargados);
        } else if (!yaModificoRef.current) {
          const inicialesT = tanquesIniciales();
          setTanques(inicialesT);
          storage.set(TANQUES_KEY, JSON.stringify(inicialesT), false).catch(() => {});
        }
      } catch (e) {
        const inicialesT = tanquesIniciales();
        setTanques(inicialesT);
        storage.set(TANQUES_KEY, JSON.stringify(inicialesT), false).catch(() => {});
      }
      setLoaded(true);
    })();
  }, []);

  const persist = async (next) => {
    try {
      const r = await storage.set(CENTRIFUGAS_KEY, JSON.stringify(next), false);
      if (!r) throw new Error("fail");
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  };

  const persistTanques = async (next) => {
    try {
      const r = await storage.set(TANQUES_KEY, JSON.stringify(next), false);
      if (!r) throw new Error("fail");
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  };

  function actualizarPunto(id, cambios) {
    yaModificoRef.current = true;
    const next = puntos.map((p) => (p.id === id ? { ...p, ...cambios } : p));
    setPuntos(next);
    persist(next);
  }

  function actualizarTanque(id, cambios) {
    yaModificoRef.current = true;
    const next = tanques.map((t) => (t.id === id ? { ...t, ...cambios } : t));
    setTanques(next);
    persistTanques(next);
  }

  const centIzquierda = puntos.filter((p) => p.pos < 10).sort((a, b) => a.pos - b.pos);
  const centDerecha = puntos.filter((p) => p.pos >= 10).sort((a, b) => a.pos - b.pos);
  const tanquesIzquierda = tanques.filter((t) => t.lado === "izquierda").sort((a, b) => a.pos - b.pos);
  const tanquesDerecha = tanques.filter((t) => t.lado === "derecha").sort((a, b) => a.pos - b.pos);
  const tanquesIntermedios = tanques.filter((t) => t.lado === "intermedio").sort((a, b) => a.pos - b.pos);
  const puntoEditando = puntos.find((p) => p.id === editando);
  const tanqueEditando = tanques.find((t) => t.id === editandoTanque);

  function Punto({ p }) {
    const color = colorPorAnio(p.anio);
    return (
      <div
        onClick={() => setEditando(p.id)}
        title={`PLFO ${p.codigo} — click para editar`}
        style={styles.filaVertical}
      >
        <div style={{
          width: 26, height: 26, borderRadius: "50%",
          background: color, border: "2px solid var(--panel-2)",
          boxShadow: "0 0 0 1px var(--border)", flexShrink: 0,
        }} />
        <div style={{ fontSize: 12.5, fontWeight: 700, color: "var(--text)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
          PLFO {p.codigo}
        </div>
      </div>
    );
  }

  function Tanque({ t }) {
    return (
      <div
        onClick={() => setEditandoTanque(t.id)}
        title={`PLFO ${t.codigo} — click para editar`}
        style={styles.filaVertical}
      >
        <div style={{
          width: 24, height: 24, borderRadius: "50%", flexShrink: 0,
          ...estiloRestauracionTanque(t.codigo),
        }} />
        <div style={{ minWidth: 0, overflow: "hidden" }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: "var(--text)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>PLFO {t.codigo}</div>
          {(t.capacidad || t.posicion) && (
            <div style={{ fontSize: 9.5, color: "var(--text-dim)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {t.capacidad}{t.capacidad && t.posicion ? " · " : ""}{t.posicion}
            </div>
          )}
        </div>
      </div>
    );
  }

  function Columna({ titulo, children }) {
    return (
      <div style={styles.columnaVertical}>
        <div style={styles.columnaVerticalTitulo}>{titulo}</div>
        {children}
      </div>
    );
  }

  function GrupoLado({ titulo, tanquesLado, centrifugasLado, centrifugasAlFinal, invertirFilas }) {
    const filaA = tanquesLado.filter((t) => t.posicion.endsWith("A")).sort((a, b) => a.pos - b.pos);
    const filaB = tanquesLado.filter((t) => t.posicion.endsWith("B")).sort((a, b) => a.pos - b.pos);
    const colFilaA = (
      <Columna titulo="Fila A">
        {filaA.map((t) => <Tanque key={t.id} t={t} />)}
      </Columna>
    );
    const colFilaB = (
      <Columna titulo="Fila B">
        {filaB.map((t) => <Tanque key={t.id} t={t} />)}
      </Columna>
    );
    const colTanques = invertirFilas ? (
      <>{colFilaB}{colFilaA}</>
    ) : (
      <>{colFilaA}{colFilaB}</>
    );
    const colCentrifugas = (
      <Columna titulo="Centrífugas">
        {centrifugasLado.map((p) => <Punto key={p.id} p={p} />)}
      </Columna>
    );
    return (
      <div style={styles.grupoLado}>
        <div style={styles.ladoTitulo}>{titulo}</div>
        <div style={styles.tresColumnas}>
          {centrifugasAlFinal ? (
            <>{colTanques}{colCentrifugas}</>
          ) : (
            <>{colCentrifugas}{colTanques}</>
          )}
        </div>
      </div>
    );
  }

  return (
    <>
      <div style={styles.headerToolbar}>
        <header style={styles.header}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ ...styles.logoBadge, background: "#FFFFFF" }}>
              <img src={ICONO_CENTRIFUGAS} alt="" style={styles.logoBadgeImg} />
            </div>
            <div>
              <div style={styles.h1}>CENTRÍFUGAS Y TANQUES</div>
              <div style={styles.sub}>Esquema de posiciones · 20 tanques y 10 centrífugas por lado</div>
            </div>
          </div>
        </header>
        {saveError && (
          <div style={styles.errorBar}>
            No se pudo guardar. Los cambios podrían perderse — reintenta la acción.
          </div>
        )}
      </div>

      {!loaded ? (
        <div style={styles.emptyState}>Cargando esquema…</div>
      ) : (
        <div style={styles.centrifugasPanel}>
          {tanquesIntermedios.length > 0 && (
            <div style={styles.tanquesIntermediosBloque}>
              <div style={styles.columnaVerticalTitulo}>Tanques intermedios</div>
              <div style={styles.tanquesIntermediosFila}>
                {tanquesIntermedios.map((t) => <Tanque key={t.id} t={t} />)}
              </div>
            </div>
          )}
          <div style={styles.ladoColumnas}>
            <GrupoLado titulo="Ala Izquierda" tanquesLado={tanquesIzquierda} centrifugasLado={centIzquierda} centrifugasAlFinal invertirFilas />
            <div style={styles.pasilloCentral}>
              <div style={styles.pasilloLinea} />
              <div style={styles.pasilloTexto}>Pasillo</div>
              <div style={styles.pasilloLinea} />
            </div>
            <GrupoLado titulo="Ala Derecha" tanquesLado={tanquesDerecha} centrifugasLado={centDerecha} centrifugasAlFinal={false} />
          </div>

          <div style={styles.centrifugasEntrada}>
            <div style={{ fontSize: 20, color: "var(--text-dim)", lineHeight: 1 }}>↑</div>
            <div style={{ fontSize: 12, color: "var(--text-dim)" }}>Entrada Pasillo</div>
          </div>

          <div style={styles.centrifugasLeyenda}>
            {ANIOS_CALIFICACION.map((a) => (
              <div key={a.anio} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <div style={{ width: 16, height: 16, borderRadius: 4, background: a.color }} />
                <span style={{ fontSize: 12.5, color: "var(--text)" }}>{a.label}</span>
              </div>
            ))}
            <span style={{ fontSize: 11, color: "var(--text-dim)" }}>(años aplican solo a centrífugas)</span>
          </div>

          <div style={styles.centrifugasLeyenda}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 16, height: 16, borderRadius: "50%", background: COLOR_RESTAURADO_2025_2026 }} />
              <span style={{ fontSize: 12.5, color: "var(--text)" }}>Restaurado — Parada 2025/2026</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 16, height: 16, borderRadius: "50%", background: COLOR_RESTAURADO_2024_2025 }} />
              <span style={{ fontSize: 12.5, color: "var(--text)" }}>Restaurado — Parada 2024/2025</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ width: 16, height: 16, borderRadius: "50%", background: `linear-gradient(90deg, ${COLOR_RESTAURADO_2024_2025} 50%, ${COLOR_RESTAURADO_2025_2026} 50%)` }} />
              <span style={{ fontSize: 12.5, color: "var(--text)" }}>Restaurado en ambas paradas</span>
            </div>
          </div>

          <div style={styles.centrifugasEstadoCard}>
            <div style={styles.centrifugasEstadoFila}>
              <span style={styles.centrifugasEstadoLabel}>Back-up:</span>
              <span style={styles.centrifugasEstadoValor}>PLFO 40</span>
            </div>
            <div style={styles.centrifugasEstadoFila}>
              <span style={styles.centrifugasEstadoLabel}>A restaurar:</span>
              <span style={styles.centrifugasEstadoValor}>PLFO 48</span>
            </div>
            <div style={styles.centrifugasEstadoFila}>
              <span style={styles.centrifugasEstadoLabel}>En taller de proveedor:</span>
              <span style={styles.centrifugasEstadoValor}>PLFO 186, PLFO 43</span>
            </div>
          </div>

        </div>
      )}

      {/* Modal de edición de una centrífuga */}
      {puntoEditando && (
        <div style={styles.overlay} onMouseDown={(e) => { if (e.target === e.currentTarget) setEditando(null); }}>
          <div style={{ ...styles.modal, maxWidth: 360 }}>
            <div style={styles.modalHeader}>
              <span style={styles.modalTitle}>Editar centrífuga</span>
              <button type="button" style={styles.iconClose} onClick={() => setEditando(null)}>
                <X size={16} />
              </button>
            </div>
            <div style={styles.modalBody}>
              <Field label="Código">
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 700, color: "var(--text-dim)" }}>PLFO</span>
                  <input
                    style={styles.input}
                    value={puntoEditando.codigo}
                    onChange={(e) => actualizarPunto(puntoEditando.id, { codigo: e.target.value })}
                  />
                </div>
              </Field>
              <Field label="Año de calificación">
                <div style={{ display: "flex", gap: 8 }}>
                  {ANIOS_CALIFICACION.map((a) => (
                    <button
                      key={a.anio}
                      type="button"
                      onClick={() => actualizarPunto(puntoEditando.id, { anio: a.anio })}
                      style={{
                        flex: 1, padding: "10px 0", borderRadius: 6, cursor: "pointer",
                        border: puntoEditando.anio === a.anio ? `2px solid ${a.color}` : "1px solid var(--border)",
                        background: puntoEditando.anio === a.anio ? `${a.color}33` : "var(--panel)",
                        color: "var(--text)", fontWeight: 700, fontSize: 13,
                        display: "flex", flexDirection: "column", alignItems: "center", gap: 4,
                      }}
                    >
                      <div style={{ width: 14, height: 14, borderRadius: "50%", background: a.color }} />
                      {a.anio}
                    </button>
                  ))}
                </div>
              </Field>
              <label style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}>
                <input
                  type="checkbox"
                  checked={!!puntoEditando.in}
                  onChange={(e) => actualizarPunto(puntoEditando.id, { in: e.target.checked })}
                  style={styles.checkbox}
                />
                <span style={{ fontSize: 13, color: "var(--text)" }}>Marcar "in"</span>
              </label>
            </div>
            <div style={styles.modalFooter}>
              <div style={{ flex: 1 }} />
              <button type="button" style={styles.btnPrimary} onClick={() => setEditando(null)}>Listo</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal de edición de un tanque */}
      {tanqueEditando && (
        <div style={styles.overlay} onMouseDown={(e) => { if (e.target === e.currentTarget) setEditandoTanque(null); }}>
          <div style={{ ...styles.modal, maxWidth: 360 }}>
            <div style={styles.modalHeader}>
              <span style={styles.modalTitle}>Editar tanque</span>
              <button type="button" style={styles.iconClose} onClick={() => setEditandoTanque(null)}>
                <X size={16} />
              </button>
            </div>
            <div style={styles.modalBody}>
              <Field label="Código">
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 700, color: "var(--text-dim)" }}>PLFO</span>
                  <input
                    style={styles.input}
                    value={tanqueEditando.codigo}
                    onChange={(e) => actualizarTanque(tanqueEditando.id, { codigo: e.target.value })}
                  />
                </div>
              </Field>
              <Field label="Capacidad">
                <input
                  style={styles.input}
                  value={tanqueEditando.capacidad}
                  onChange={(e) => actualizarTanque(tanqueEditando.id, { capacidad: e.target.value })}
                  placeholder="Ej: 8000 L"
                />
              </Field>
              <Field label="Posición">
                <input
                  style={styles.input}
                  value={tanqueEditando.posicion}
                  onChange={(e) => actualizarTanque(tanqueEditando.id, { posicion: e.target.value })}
                  placeholder="Ej: 11B"
                />
              </Field>
            </div>
            <div style={styles.modalFooter}>
              <div style={{ flex: 1 }} />
              <button type="button" style={styles.btnPrimary} onClick={() => setEditandoTanque(null)}>Listo</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

/* ---------------------- Proveedores ---------------------- */

// Columnas de la grilla. Las que tienen "compuesto" muestran 2 subcampos
// dentro de la misma celda (un checkbox que habilita al segundo campo, o
// un valor + un desplegable de moneda).
const PROVEEDORES_COLUMNAS = [
  { id: "nombre", label: "Nombre", compuesto: null, ancho: 160 },
  { id: "descripcionTrabajo", label: "Descripción de trabajo", compuesto: null, ancho: 220 },
  { id: "monto", label: "Monto", compuesto: "moneda", ancho: 160 },
  { id: "solicitado", label: "Solicitado", compuesto: "checkSimple", ancho: 90 },
  { id: "rma", label: "RMA", compuesto: "checkNumero", ancho: 110 },
  { id: "oc", label: "OC", compuesto: "checkNumero", ancho: 110 },
  { id: "anticipo", label: "Anticipo", compuesto: "checkPorcentaje", ancho: 190 },
  { id: "documentacionIngreso", label: "Documentación de ingreso", compuesto: "checkSolo", ancho: 180 },
  { id: "capacitacion", label: "Capacitación", compuesto: "checkFecha", ancho: 180 },
  { id: "presupuesto", label: "Presupuesto", compuesto: "archivo", ancho: 170 },
];

function proveedorVacio() {
  return {
    id: uid(),
    nombre: "",
    descripcionTrabajo: "",
    monto: { valor: "", moneda: "ARS" },
    solicitado: false,
    rma: { tildado: false, numero: "" },
    oc: { tildado: false, numero: "" },
    anticipo: { tildado: false, porcentaje: "" },
    documentacionIngreso: { tildado: false },
    capacitacion: { tildado: false, fecha: "" },
    presupuesto: { nombreArchivo: "", datos: "" },
  };
}

// Migra proveedores viejos (de la versión anterior, con campos planos de
// texto) al nuevo modelo con subcampos, para no romper datos ya guardados.
function migrarProveedor(p) {
  const base = proveedorVacio();
  const esObjeto = (v) => v && typeof v === "object" && !Array.isArray(v);
  return {
    ...base,
    ...p,
    monto: esObjeto(p.monto) ? { ...base.monto, ...p.monto } : { ...base.monto, valor: p.monto || "" },
    rma: esObjeto(p.rma) ? { ...base.rma, ...p.rma } : { ...base.rma, numero: p.rma || "" },
    oc: esObjeto(p.oc) ? { ...base.oc, ...p.oc } : { ...base.oc, numero: p.oc || "" },
    anticipo: esObjeto(p.anticipo) ? { ...base.anticipo, ...p.anticipo } : { ...base.anticipo, porcentaje: p.anticipo || "" },
    documentacionIngreso: esObjeto(p.documentacionIngreso) ? { ...base.documentacionIngreso, ...p.documentacionIngreso } : { tildado: !!p.documentacionIngreso },
    capacitacion: esObjeto(p.capacitacion) ? { ...base.capacitacion, ...p.capacitacion } : { tildado: false, fecha: p.fechaCapacitacion || "" },
  };
}

// Componente de celda fuera de ProveedoresTab a propósito: si se define
// adentro, React lo recrea en cada render y los inputs pierden el foco
// después de cada letra tipeada.
// Formatea un monto mientras se escribe: "," para miles y "." para decimales
// (ej: 1234567.5 -> "1,234,567.5"). Deja como máximo 2 dígitos decimales.
function formatearMonto(raw) {
  let limpio = raw.replace(/[^0-9.]/g, "");
  const primerPunto = limpio.indexOf(".");
  if (primerPunto !== -1) {
    limpio = limpio.slice(0, primerPunto + 1) + limpio.slice(primerPunto + 1).replace(/\./g, "");
  }
  const [enteroCrudo, decimalCrudo] = limpio.split(".");
  const entero = (enteroCrudo || "").replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  if (decimalCrudo === undefined) {
    return limpio.endsWith(".") ? entero + "." : entero;
  }
  return entero + "." + decimalCrudo.slice(0, 2);
}

// Vuelve un monto formateado ("1,234.5") a número (1234.5), para poder
// calcular con él (ej: el monto de anticipo según el %).
function parsearMonto(valorFormateado) {
  const n = parseFloat(String(valorFormateado || "").replace(/,/g, ""));
  return isNaN(n) ? 0 : n;
}

// Determina si una celda de RMA/OC/Presupuesto ya está cargada, para
// pintarla de verde como indicador visual de "completo".
function celdaProveedorCompleta(p, col) {
  if (col.id === "solicitado") return !!p.solicitado;
  if (col.id === "rma") return !!(p.rma && p.rma.tildado && p.rma.numero);
  if (col.id === "oc") return !!(p.oc && p.oc.tildado && p.oc.numero);
  if (col.id === "presupuesto") return !!(p.presupuesto && p.presupuesto.datos);
  if (col.id === "capacitacion") return !!(p.capacitacion && p.capacitacion.tildado && p.capacitacion.fecha);
  return false;
}

function CeldaProveedor({ p, col, actualizarCampoSimple, actualizarSubcampo }) {
  if (col.compuesto === null) {
    return (
      <input
        type="text"
        style={styles.proveedoresInput}
        value={p[col.id] || ""}
        onChange={(e) => actualizarCampoSimple(p.id, col.id, e.target.value)}
      />
    );
  }
  if (col.compuesto === "moneda") {
    return (
      <div style={styles.proveedoresCompuesto}>
        <span style={{ fontSize: 12, color: "var(--text-dim)", flexShrink: 0 }}>$</span>
        <input
          type="text"
          style={{ ...styles.proveedoresInput, flex: 1 }}
          placeholder="0"
          value={p.monto.valor}
          onChange={(e) => actualizarSubcampo(p.id, "monto", "valor", formatearMonto(e.target.value))}
        />
        <select
          style={styles.proveedoresSelect}
          value={p.monto.moneda}
          onChange={(e) => actualizarSubcampo(p.id, "monto", "moneda", e.target.value)}
        >
          <option value="ARS">ARS</option>
          <option value="USD">USD</option>
        </select>
      </div>
    );
  }
  if (col.compuesto === "checkNumero") {
    const obj = p[col.id];
    return (
      <div style={styles.proveedoresCompuesto}>
        <input
          type="checkbox"
          checked={obj.tildado}
          onChange={(e) => actualizarSubcampo(p.id, col.id, "tildado", e.target.checked)}
          style={styles.checkbox}
        />
        {obj.tildado && (
          <input
            type="text"
            maxLength={6}
            style={{ ...styles.proveedoresInputRedondeado, width: 62, flex: "0 0 auto" }}
            placeholder="N°"
            value={obj.numero}
            onChange={(e) => actualizarSubcampo(p.id, col.id, "numero", e.target.value)}
          />
        )}
      </div>
    );
  }
  if (col.compuesto === "checkPorcentaje") {
    const obj = p.anticipo;
    return (
      <div style={styles.proveedoresCompuesto}>
        <input
          type="checkbox"
          checked={obj.tildado}
          onChange={(e) => actualizarSubcampo(p.id, "anticipo", "tildado", e.target.checked)}
          style={styles.checkbox}
        />
        {obj.tildado && (
          <div style={{ display: "flex", alignItems: "center", gap: 2, flex: "0 0 auto", width: 44, ...styles.proveedoresInputRedondeado, padding: "3px 6px" }}>
            <input
              type="text"
              maxLength={2}
              style={{ background: "transparent", border: "none", outline: "none", color: "var(--text)", fontSize: 12, width: "100%", padding: 0 }}
              placeholder="0"
              value={obj.porcentaje}
              onChange={(e) => actualizarSubcampo(p.id, "anticipo", "porcentaje", e.target.value)}
            />
            {obj.porcentaje && <span style={{ fontSize: 12, color: "var(--text-dim)", flexShrink: 0 }}>%</span>}
          </div>
        )}
        {obj.tildado && obj.porcentaje && (
          <span style={{ fontSize: 12.5, color: "var(--text-dim)", flexShrink: 0, whiteSpace: "nowrap" }}>
            ${formatearMonto((parsearMonto(p.monto.valor) * (parseFloat(obj.porcentaje) || 0) / 100).toFixed(2))} {p.monto.moneda}
          </span>
        )}
      </div>
    );
  }
  if (col.compuesto === "checkSimple") {
    return (
      <div style={{ display: "flex", justifyContent: "center" }}>
        <input
          type="checkbox"
          checked={!!p[col.id]}
          onChange={(e) => actualizarCampoSimple(p.id, col.id, e.target.checked)}
          style={styles.checkbox}
        />
      </div>
    );
  }
  if (col.compuesto === "checkSolo") {
    const obj = p.documentacionIngreso;
    return (
      <div style={styles.proveedoresCompuesto}>
        <input
          type="checkbox"
          checked={obj.tildado}
          onChange={(e) => actualizarSubcampo(p.id, "documentacionIngreso", "tildado", e.target.checked)}
          style={styles.checkbox}
        />
        <span style={{ fontSize: 12, color: obj.tildado ? "#6FA97A" : "var(--text-dim)", fontWeight: 600 }}>
          {obj.tildado ? "Ingresa" : "Sin documentación cargada"}
        </span>
      </div>
    );
  }
  if (col.compuesto === "checkFecha") {
    const obj = p.capacitacion;
    return (
      <div style={styles.proveedoresCompuesto}>
        <input
          type="checkbox"
          checked={obj.tildado}
          onChange={(e) => actualizarSubcampo(p.id, "capacitacion", "tildado", e.target.checked)}
          style={styles.checkbox}
        />
        {obj.tildado && (
          <input
            type="date"
            style={{ ...styles.proveedoresInputRedondeado, flex: 1 }}
            value={obj.fecha}
            onChange={(e) => actualizarSubcampo(p.id, "capacitacion", "fecha", e.target.value)}
          />
        )}
      </div>
    );
  }
  if (col.compuesto === "archivo") {
    const obj = p.presupuesto || { nombreArchivo: "", datos: "" };
    function onFileChange(e) {
      const archivo = e.target.files && e.target.files[0];
      if (!archivo) return;
      const lector = new FileReader();
      lector.onload = () => {
        actualizarSubcampo(p.id, "presupuesto", "nombreArchivo", archivo.name);
        actualizarSubcampo(p.id, "presupuesto", "datos", lector.result);
      };
      lector.readAsDataURL(archivo);
      e.target.value = "";
    }
    if (obj.datos) {
      return (
        <div style={styles.proveedoresArchivoFila}>
          <a
            href={obj.datos}
            download={obj.nombreArchivo || "presupuesto"}
            style={styles.proveedoresArchivoLink}
            title={obj.nombreArchivo}
          >
            📎 {obj.nombreArchivo || "archivo"}
          </a>
          <button
            type="button"
            style={styles.subtaskDelete}
            title="Quitar archivo"
            onClick={() => {
              actualizarSubcampo(p.id, "presupuesto", "nombreArchivo", "");
              actualizarSubcampo(p.id, "presupuesto", "datos", "");
            }}
          >
            <X size={12} />
          </button>
        </div>
      );
    }
    return (
      <label style={styles.proveedoresArchivoBoton}>
        <Upload size={12} /> Adjuntar
        <input type="file" onChange={onFileChange} style={{ display: "none" }} />
      </label>
    );
  }
  return null;
}

function ProveedoresTab() {
  const [proveedores, setProveedores] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [saveError, setSaveError] = useState(false);
  const yaModificoRef = useRef(false);
  const [filtroNombre, setFiltroNombre] = useState("");
  const [filtroRma, setFiltroRma] = useState("");
  const [filtroOc, setFiltroOc] = useState("");

  const [anchosColumnas, setAnchosColumnas] = useState(() => {
    const obj = {};
    PROVEEDORES_COLUMNAS.forEach((c) => { obj[c.id] = c.ancho; });
    return obj;
  });
  const resizingRef = useRef(null); // { colId, startX, startWidth } | null

  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(PROVEEDORES_ANCHOS_KEY, false);
        if (res && res.value) {
          setAnchosColumnas((prev) => ({ ...prev, ...JSON.parse(res.value) }));
        }
      } catch (e) {
        /* no existe aún */
      }
    })();
  }, []);

  function iniciarResize(e, colId) {
    e.preventDefault();
    resizingRef.current = { colId, startX: e.clientX, startWidth: anchosColumnas[colId] };
    const onMove = (ev) => {
      if (!resizingRef.current) return;
      const delta = ev.clientX - resizingRef.current.startX;
      const nuevoAncho = Math.max(60, resizingRef.current.startWidth + delta);
      setAnchosColumnas((prev) => ({ ...prev, [resizingRef.current.colId]: nuevoAncho }));
    };
    const onUp = () => {
      resizingRef.current = null;
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      setAnchosColumnas((prev) => {
        storage.set(PROVEEDORES_ANCHOS_KEY, JSON.stringify(prev), false).catch(() => {});
        return prev;
      });
    };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
  }

  useEffect(() => {
    (async () => {
      try {
        const res = await storage.get(PROVEEDORES_KEY, false);
        if (res && res.value && !yaModificoRef.current) {
          setProveedores(JSON.parse(res.value).map(migrarProveedor));
        }
      } catch (e) {
        /* no existe aún */
      }
      setLoaded(true);
    })();
  }, []);

  const persist = async (next) => {
    try {
      const r = await storage.set(PROVEEDORES_KEY, JSON.stringify(next), false);
      if (!r) throw new Error("fail");
      setSaveError(false);
    } catch (e) {
      setSaveError(true);
    }
  };

  function actualizar(next) {
    yaModificoRef.current = true;
    setProveedores(next);
    persist(next);
  }

  function agregarProveedor() {
    actualizar([...proveedores, proveedorVacio()]);
  }

  // Para nombre y descripción (campos simples, sin subcampos)
  function actualizarCampoSimple(id, campo, valor) {
    actualizar(proveedores.map((p) => (p.id === id ? { ...p, [campo]: valor } : p)));
  }

  // Para monto/rma/oc/anticipo/documentacionIngreso/capacitacion (objetos con subcampos)
  function actualizarSubcampo(id, campo, sub, valor) {
    actualizar(proveedores.map((p) => (p.id === id ? { ...p, [campo]: { ...p[campo], [sub]: valor } } : p)));
  }

  function eliminarProveedor(id) {
    actualizar(proveedores.filter((p) => p.id !== id));
  }

  const proveedoresFiltrados = proveedores.filter((p) => {
    const okNombre = !filtroNombre || (p.nombre || "").toLowerCase().includes(filtroNombre.toLowerCase());
    const okRma = !filtroRma || (p.rma.numero || "").toLowerCase().includes(filtroRma.toLowerCase());
    const okOc = !filtroOc || (p.oc.numero || "").toLowerCase().includes(filtroOc.toLowerCase());
    return okNombre && okRma && okOc;
  });

  const totalArs = proveedoresFiltrados
    .filter((p) => p.monto.moneda === "ARS")
    .reduce((s, p) => s + parsearMonto(p.monto.valor), 0);
  const totalUsd = proveedoresFiltrados
    .filter((p) => p.monto.moneda === "USD")
    .reduce((s, p) => s + parsearMonto(p.monto.valor), 0);

  function montoAnticipo(p) {
    if (!p.anticipo.tildado || !p.anticipo.porcentaje) return 0;
    return parsearMonto(p.monto.valor) * (parseFloat(p.anticipo.porcentaje) || 0) / 100;
  }
  const totalAnticipoArs = proveedoresFiltrados
    .filter((p) => p.monto.moneda === "ARS")
    .reduce((s, p) => s + montoAnticipo(p), 0);
  const totalAnticipoUsd = proveedoresFiltrados
    .filter((p) => p.monto.moneda === "USD")
    .reduce((s, p) => s + montoAnticipo(p), 0);

  return (
    <>
      <div style={styles.headerToolbar}>
        <header style={styles.header}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <div style={{ ...styles.logoBadge, background: "transparent" }}>
              <img src={ICONO_PROVEEDORES} alt="" style={{ width: 34, height: 34, objectFit: "contain" }} />
            </div>
            <div>
              <div style={styles.h1}>PROVEEDORES</div>
              <div style={styles.sub}>Grilla de proveedores para parada de planta · {proveedores.length} proveedor{proveedores.length !== 1 ? "es" : ""}</div>
            </div>
          </div>
          <button
            style={{ ...styles.btnPrimary, opacity: loaded ? 1 : 0.5, cursor: loaded ? "pointer" : "not-allowed" }}
            onClick={agregarProveedor}
            disabled={!loaded}
          >
            <Plus size={16} /> {loaded ? "Nuevo proveedor" : "Cargando..."}
          </button>
        </header>
        {saveError && (
          <div style={styles.errorBar}>
            No se pudo guardar. Los cambios podrían perderse — reintenta la acción.
          </div>
        )}
      </div>

      {loaded && proveedores.length > 0 && (
        <div style={styles.proveedoresFiltrosFila}>
          <input
            style={{ ...styles.inputSmall, width: 200 }}
            placeholder="Filtrar por Nombre..."
            value={filtroNombre}
            onChange={(e) => setFiltroNombre(e.target.value)}
          />
          <input
            style={{ ...styles.inputSmall, width: 200 }}
            placeholder="Filtrar por RMA..."
            value={filtroRma}
            onChange={(e) => setFiltroRma(e.target.value)}
          />
          <input
            style={{ ...styles.inputSmall, width: 200 }}
            placeholder="Filtrar por OC..."
            value={filtroOc}
            onChange={(e) => setFiltroOc(e.target.value)}
          />
          <div style={styles.proveedoresTotalesGrupo}>
            <div style={styles.proveedoresTotalBox}>
              <span style={{ fontWeight: 700 }}>Total:</span> ${formatearMonto(totalArs.toFixed(2))} ARS
              {totalUsd > 0 && <> · ${formatearMonto(totalUsd.toFixed(2))} USD</>}
            </div>
            <div style={styles.proveedoresTotalBox}>
              <span style={{ fontWeight: 700 }}>Total anticipos:</span> ${formatearMonto(totalAnticipoArs.toFixed(2))} ARS
              {totalAnticipoUsd > 0 && <> · ${formatearMonto(totalAnticipoUsd.toFixed(2))} USD</>}
            </div>
          </div>
        </div>
      )}

      {!loaded ? (
        <div style={styles.emptyState}>Cargando proveedores…</div>
      ) : proveedores.length === 0 ? (
        <div style={styles.emptyState}>
          Todavía no hay proveedores cargados. Creá el primero con "Nuevo proveedor".
        </div>
      ) : proveedoresFiltrados.length === 0 ? (
        <div style={styles.emptyState}>
          Ningún proveedor coincide con los filtros aplicados.
        </div>
      ) : (
        <div style={styles.proveedoresScroll} className="scrollbar">
          <table style={{ ...styles.proveedoresTabla, tableLayout: "fixed" }}>
            <thead>
              <tr>
                {PROVEEDORES_COLUMNAS.map((col) => (
                  <th key={col.id} style={{ ...styles.proveedoresTh, width: anchosColumnas[col.id], position: "relative" }}>
                    {col.label}
                    <div
                      onMouseDown={(e) => iniciarResize(e, col.id)}
                      title="Arrastrar para cambiar el ancho"
                      style={styles.proveedoresResizeHandle}
                    />
                  </th>
                ))}
                <th style={{ ...styles.proveedoresTh, width: 40 }} />
              </tr>
            </thead>
            <tbody>
              {proveedoresFiltrados.map((p) => (
                <tr key={p.id}>
                  {PROVEEDORES_COLUMNAS.map((col) => (
                    <td
                      key={col.id}
                      style={{
                        ...styles.proveedoresTd,
                        background: celdaProveedorCompleta(p, col) ? "rgba(111, 169, 122, 0.22)" : styles.proveedoresTd.background,
                      }}
                    >
                      <CeldaProveedor
                        p={p}
                        col={col}
                        actualizarCampoSimple={actualizarCampoSimple}
                        actualizarSubcampo={actualizarSubcampo}
                      />
                    </td>
                  ))}
                  <td style={{ ...styles.proveedoresTd, textAlign: "center" }}>
                    <button
                      onClick={() => eliminarProveedor(p.id)}
                      style={styles.subtaskDelete}
                      title="Eliminar proveedor"
                    >
                      <X size={13} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
}

